//! Known-answer tests against the CPython-verified corpus
//! (`tests/vectors/cpython_kat.tsv`, generated by scripts/gen_vectors.py).
//! Every expected value in the corpus was computed with CPython's own
//! arbitrary-precision integers, making this a true differential-vs-CPython
//! gate inside `cargo test` (spec 6 / 10).

use meganum_core::bigint::{BigInt, Sign};
use meganum_core::biguint::BigUInt;

fn parse_i(s: &str) -> BigInt {
    BigInt::parse(s).expect("corpus operand must parse")
}

fn fmt_i(v: &BigInt) -> String {
    v.to_string_radix(10).expect("decimal render")
}

/// Compute one corpus row with the engine; CPython's expected value is
/// compared by the caller.
fn row_result(op: &str, a: &str, b: &str) -> Result<String, String> {
    let av = parse_i(a);
    match op {
        "add" => Ok(fmt_i(&av.add(&parse_i(b)))),
        "sub" => Ok(fmt_i(&av.sub(&parse_i(b)))),
        "mul" => Ok(fmt_i(&av.mul(&parse_i(b)))),
        "floordiv" => {
            let bv = parse_i(b);
            if bv.is_zero() {
                Err("zero divisor in corpus".to_string())
            } else {
                Ok(fmt_i(&av.floordiv(&bv).expect("divisor nonzero")))
            }
        }
        "mod" => {
            let bv = parse_i(b);
            if bv.is_zero() {
                Err("zero divisor in corpus".to_string())
            } else {
                Ok(fmt_i(&av.rem_floor(&bv).expect("divisor nonzero")))
            }
        }
        "and" => Ok(fmt_i(&av.bit_and(&parse_i(b)))),
        "or" => Ok(fmt_i(&av.bit_or(&parse_i(b)))),
        "xor" => Ok(fmt_i(&av.bit_xor(&parse_i(b)))),
        "neg" => Ok(fmt_i(&av.neg())),
        "not" => Ok(fmt_i(&av.bit_not())),
        "abs" => Ok(fmt_i(&av.abs())),
        "pow" => {
            let e: u64 = b.parse().map_err(|_| "bad exponent".to_string())?;
            Ok(fmt_i(&av.pow_u64(e)))
        }
        "shl" => {
            let k: usize = b.parse().map_err(|_| "bad shift".to_string())?;
            Ok(fmt_i(&av.shl(k)))
        }
        "shr" => {
            let k: usize = b.parse().map_err(|_| "bad shift".to_string())?;
            Ok(fmt_i(&av.shr(k)))
        }
        "to_base" => {
            let radix: u32 = b.parse().map_err(|_| "bad radix".to_string())?;
            av.to_string_radix(radix).map_err(|e| e.to_string())
        }
        other => Err(format!("unknown op {other}")),
    }
}

#[test]
fn cpython_kat_corpus() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/vectors/cpython_kat.tsv");
    let text = std::fs::read_to_string(&path).expect("KAT corpus must exist");
    let mut rows = 0usize;
    let mut failures: Vec<String> = Vec::new();
    for (lineno, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let cols: Vec<&str> = line.split('\t').collect();
        if cols.len() != 5 {
            failures.push(format!("line {}: expected 5 columns", lineno + 1));
            continue;
        }
        let (op, a, b, _extra, expected) = (cols[0], cols[1], cols[2], cols[3], cols[4]);
        rows += 1;
        match row_result(op, a, b) {
            Ok(got) => {
                if got != expected {
                    failures.push(format!(
                        "line {}: {op}({a}, {b}) = {got}, CPython says {expected}",
                        lineno + 1
                    ));
                }
            }
            Err(e) => failures.push(format!("line {}: {e}", lineno + 1)),
        }
    }
    assert!(rows >= 1000, "corpus should be substantial, got {rows}");
    assert!(
        failures.is_empty(),
        "{} of {rows} KAT rows failed:\n{}",
        failures.len(),
        failures
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn parse_prefixes_match_cpython_semantics() {
    // Cross-checks of prefix/underscore handling against Python literals.
    let cases: &[(&str, i128)] = &[
        ("0x10", 16),
        ("0o10", 8),
        ("0b10", 2),
        ("1_000", 1_000),
        ("0xff_ff", 65_535),
        ("-0x1F", -31),
        ("+123", 123),
    ];
    for (s, want) in cases {
        let got = BigInt::parse(s).unwrap();
        assert_eq!(got.to_i64().map(|v| v as i128), Some(*want), "parse {s}");
    }
    assert!(BigInt::parse("0b12").is_err());
    assert!(BigInt::parse("_5").is_err());
    assert!(BigInt::parse("5_").is_err());
    assert!(BigInt::parse("__5").is_err());
}

#[test]
fn zero_and_sign_canonicalization() {
    assert_eq!(BigInt::new(Sign::Negative, BigUInt::zero()), BigInt::zero());
    assert!(!BigInt::zero().is_negative());
}
